package io.aetheris.orchestrator.trading;
import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Service public class MultiSourceMarketDataBook {private final Map<String,Map<String,MarketDataSnapshot>>data=new ConcurrentHashMap<>();private final MarketConsensusEvidenceRepository evidence;public MultiSourceMarketDataBook(MarketConsensusEvidenceRepository evidence){this.evidence=evidence;}public MarketDataSnapshot ingest(MarketDataSnapshot s){if(s==null||s.symbol()==null||s.symbol().isBlank()||s.source()==null||s.source().isBlank()||s.bars().isEmpty())throw new IllegalArgumentException("symbol, source and bars are required");for(MarketBar b:s.bars())if(b.close()<=0||b.high()<b.low())throw new IllegalArgumentException("Invalid market bar");MarketDataSnapshot n=new MarketDataSnapshot(s.symbol().trim().toUpperCase(Locale.ROOT),s.source().trim().toLowerCase(Locale.ROOT),s.observedAt()==null?Instant.now():s.observedAt(),s.bars());data.computeIfAbsent(n.symbol(),k->new ConcurrentHashMap<>()).put(n.source(),n);return n;}public MarketConsensus consensus(String symbol,int minSources,long maxAgeSeconds,long maxClockSkewSeconds,double maxDivergencePct){String key=symbol.trim().toUpperCase(Locale.ROOT);Map<String,MarketDataSnapshot>m=data.getOrDefault(key,Map.of());Instant now=Instant.now();List<MarketDataSnapshot>fresh=new ArrayList<>();for(MarketDataSnapshot s:m.values()){long future=Duration.between(now,s.observedAt()).toSeconds();if(future>Math.max(1,maxClockSkewSeconds))throw new IllegalStateException("Market source clock is too far in the future: "+s.source());Duration age=Duration.between(s.observedAt(),now);if(age.isNegative())age=Duration.ZERO;if(age.getSeconds()<=Math.max(1,maxAgeSeconds))fresh.add(s);}if(fresh.size()<Math.max(2,minSources))throw new IllegalStateException("Insufficient fresh independent market sources for "+key);Instant oldest=fresh.stream().map(MarketDataSnapshot::observedAt).min(Instant::compareTo).orElse(now),newest=fresh.stream().map(MarketDataSnapshot::observedAt).max(Instant::compareTo).orElse(now);long skew=Math.abs(Duration.between(oldest,newest).toSeconds());if(skew>Math.max(1,maxClockSkewSeconds))throw new IllegalStateException("Market source clock skew exceeds policy");List<Double>last=fresh.stream().map(x->x.bars().getLast().close()).sorted().toList();double median=median(last),min=last.getFirst(),max=last.getLast(),div=median<=0?100:(max-min)/median*100;if(div>Math.max(0.01,maxDivergencePct))throw new IllegalStateException("Market sources disagree beyond price divergence policy");int bars=fresh.stream().mapToInt(x->x.bars().size()).min().orElse(0);List<MarketBar>merged=new ArrayList<>();for(int offset=bars;offset>0;offset--){final int indexFromEnd=offset;List<MarketBar>slice=fresh.stream().map(x->x.bars().get(x.bars().size()-indexFromEnd)).toList();merged.add(new MarketBar(slice.stream().map(MarketBar::time).max(Comparator.naturalOrder()).orElse(oldest),median(slice.stream().map(MarketBar::open).sorted().toList()),median(slice.stream().map(MarketBar::high).sorted().toList()),median(slice.stream().map(MarketBar::low).sorted().toList()),median(slice.stream().map(MarketBar::close).sorted().toList()),median(slice.stream().map(MarketBar::volume).sorted().toList())));}List<String>sources=fresh.stream().map(MarketDataSnapshot::source).sorted().toList();MarketConsensus c=new MarketConsensus(new MarketDataSnapshot(key,"stage9-consensus",oldest,merged),sources,median,div,skew);evidence.save(new MarketConsensusEvidenceEntity(UUID.randomUUID(),c));return c;}public List<Double> consensusCloses(String symbol,int minSources,long maxAge,long maxSkew,double maxDiv){return consensus(symbol,minSources,maxAge,maxSkew,maxDiv).snapshot().bars().stream().map(MarketBar::close).toList();}public List<MarketConsensusEvidenceEntity> recentEvidence(){return evidence.findTop100ByOrderByCreatedAtDesc();}private double median(List<Double>v){if(v.isEmpty())return 0;int n=v.size();return n%2==1?v.get(n/2):(v.get(n/2-1)+v.get(n/2))/2;}}
